456	fn complete_candidates_str(
457	    value: &str,
458	    mut values: Vec<CompletionCandidate>,
459	) -> Vec<CompletionCandidate> {
460	    debug!("complete_candidates_str: value={value:?}");
461	
462	    values.retain(|comp| comp.get_value().starts_with(value));
463	    values
464	}
