14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    let mut current_cmd = &*cmd;
36	    if cmd.is_multicall_set() {
37	        // A multicall binary dispatches on argv0: the applet is selected by the
38	        // file stem of the invoked path, mirroring runtime parsing.
39	        let applet = raw_args.next_os(&mut cursor).and_then(|argv0| {
40	            std::path::Path::new(argv0)
41	                .file_stem()
42	                .map(|s| s.to_owned())
43	        });
44	        let Some(applet) = applet else {
45	            return Ok(Vec::new());
46	        };
47	        let Some(applet_cmd) = cmd.find_subcommand(&applet) else {
48	            // Unknown applets must not leak the known applet names
49	            return Ok(Vec::new());
50	        };
51	        current_cmd = applet_cmd;
52	    } else if !cmd.is_no_binary_name_set() {
53	        raw_args.next_os(&mut cursor);
54	    }
55	    let mut pos_index = 1;
56	    let mut is_escaped = false;
57	    let mut next_state = ParseState::ValueDone;
58	    while let Some(arg) = raw_args.next(&mut cursor) {
59	        let current_state = next_state;
60	        next_state = ParseState::ValueDone;
61	        debug!(
62	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
63	            arg.to_value_os(),
64	        );
65	        if cursor == target_cursor {
66	            return complete_arg(
67	                &arg,
68	                current_cmd,
69	                current_dir,
70	                pos_index,
71	                is_escaped,
72	                current_state,
73	            );
74	        }
75	
76	        if let Ok(value) = arg.to_value() {
77	            if let Some(next_cmd) = current_cmd.find_subcommand(value) {
78	                current_cmd = next_cmd;
79	                pos_index = 1;
80	                continue;
81	            }
82	        }
83	
84	        if is_escaped {
85	            (next_state, pos_index) =
